74	    /// <inheritdoc />
75	    public virtual async IAsyncEnumerable<string> ListCollectionNamesAsync([EnumeratorCancellation] CancellationToken cancellationToken = default)
76	    {
77	        const string TablePropertyName = "name";
78	        const string Query = $"SELECT {TablePropertyName} FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%';";
79	
80	        using var command = this._connection.CreateCommand();
81	
82	        command.CommandText = Query;
83	
84	        using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);
85	
86	        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
87	        {
88	            var ordinal = reader.GetOrdinal(TablePropertyName);
89	            yield return reader.GetString(ordinal);
90	        }
91	    }
